<script>
import TitleLine from './modules/TitleLine'
import { getGameLsitbyown, getGameplayHotList } from '@/api/game'
import { getGameplayList, gotoGame } from '@/api/user'
import hxyx_1 from '@/assets/portal/home/hxyx_1.png'
import hxyx_2 from '@/assets/portal/home/hxyx_2.png'
import hxyx_3 from '@/assets/portal/home/hxyx_3.png'
import hxyx_4 from '@/assets/portal/home/hxyx_4.png'
import hxyx_5 from '@/assets/portal/home/hxyx_5.png'
import hxyx_6 from '@/assets/portal/home/hxyx_6.png'
import hxyx_7 from '@/assets/portal/home/hxyx_7.png'
import hxyx_8 from '@/assets/portal/home/hxyx_8.png'
import hxyx_101 from '@/assets/portal/home/hxyx_101.png'
import hxyx_102 from '@/assets/portal/home/hxyx_102.png'
import hxyx_103 from '@/assets/portal/home/hxyx_103.png'
import hxyx_104 from '@/assets/portal/home/hxyx_104.png'
import hxyx_105 from '@/assets/portal/home/hxyx_105.png'
import hxyx_106 from '@/assets/portal/home/hxyx_106.png'
import hxyx_107 from '@/assets/portal/home/hxyx_107.png'
import hxyx_108 from '@/assets/portal/home/hxyx_108.png'
import active_nav_all from '@/assets/portal/active-nav-all.png'
import nav_all from '@/assets/portal/nav-all.png'
export default {
  components: {
    TitleLine
  },
  data() {
    return {
      clickStatus: false,
      currentValue: '888',
      showPop: false,
      title: '电子游戏',
      searchText: '',
      currentTab: 0,
      gamemenutype: '1',
      redbaghbid: null,
      gameTypeList: [{ activeurl: active_nav_all, gamemenutype: '888', gametype: '888', gametypename: this.$t('home.sy09'), gametypeurl: 'https://img.rr888.vip/img/ztb-dtqp.jpg', order: '', smallurl: nav_all, status: '0' }],
      playGameList: [],
      allGameList: [],
      typeList1: [{
        imgUrl: hxyx_8, label: this.$t('hxhash.hx01'),
        value: 'gameZH'
      }, {
        imgUrl: hxyx_2, label: this.$t('hxhash.hx79'),
        value: 'gameSP'
      }, {
        imgUrl: hxyx_1, label: this.$t('hxhash.hx81'),
        value: 'gameDX'
      }, {
        imgUrl: hxyx_5, label: this.$t('hxhash.hx80'),
        value: 'gameBull'
      }, {
        imgUrl: hxyx_4, label: this.$t('hxhash.hx82'),
        value: 'gameZX'
      }, {
        imgUrl: hxyx_3, label: this.$t('hxhash.hx83'),
        value: 'gameXY'
      }, {
        imgUrl: hxyx_6, label: this.$t('hxhash.hx84'),
        value: 'gameDiceSP'
      }, {
        imgUrl: hxyx_7, label: this.$t('hxhash.hx85'),
        value: 'gameDiceDX'
      }

      ],
      typeList2: [{
        imgUrl: hxyx_108, label: '哈希1分综合',
        value: 'gameMinuZH'
      }, {
        imgUrl: hxyx_102, label: '哈希1分单双',
        value: 'gameMinuSP'
      }, {
        imgUrl: hxyx_101, label: '哈希1分大小',
        value: 'gameMinuDX'
      }, {
        imgUrl: hxyx_105, label: '哈希1分牛牛',
        value: 'gameMinuBull'
      }, {
        imgUrl: hxyx_103, label: '哈希1分幸运',
        value: 'gameMinuXY'
      }, {
        imgUrl: hxyx_104, label: '哈希1分庄闲',
        value: 'gameMinuZX'
      }, {
        imgUrl: hxyx_106, label: '骰子1分单双',
        value: 'gameMinuDiceSP'
      }, {
        imgUrl: hxyx_107, label: '骰子1分大小',
        value: 'gameMinuDiceDX'
      }
      // {
      //   imgUrl: hxyx_107, label: '哈希1分综合',
      //   value: 'gameMinuZH'
      // }
      ]
    }
  },
  async mounted() {
    this.token = this.$store.getters.token
    if (this.$route.query.gamemenutype) {
      this.gamemenutype = this.$route.query.gamemenutype
      this.title = this.gamemenutype === '1' ? '电子游戏' : (this.gamemenutype === '2' ? '棋牌游戏' : (this.gamemenutype === '3' ? '真人视讯' : '体育竞猜'))
    }
    // if (this.$route.query.hbid) {
    //   this.redbaghbid = this.$route.query.hbid
    // }
    const res = await getGameplayList({ gamemenutype: 0 })
    // const res=getGameLsitbyown({ gametype:'0',gamemenutype:'1' })
    this.gameTypeList = this.gameTypeList.concat(res.datalist)
    this.currentTab = this.gameTypeList.findIndex(item => {
      return item.gametype === this.$route.query.gametype
    })
    this.currentValue = this.gameTypeList[this.currentTab].gametype // 下拉框定位到某一项
    await this.$nextTick()
    const navList = document.getElementsByClassName('navList')
    const navWidth = document.getElementsByClassName('nav')[0].clientWidth
    navList[0].scroll({
      top: 0,
      left: (this.currentTab - 2) * navWidth,
      behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
    })
    this.loadGame(this.$route.query.gametype, this.$route.query.gamemenutype)
    // this.loadGame('0', '888')
  },
  methods: {
    onCancel() {
      this.playGameList = this.allGameList
    },
    async tabClick(item, index) {
      this.currentTab = index
      this.currentValue = item.gametype
      this.showPop = false
      await this.$nextTick()
      const navList = document.getElementsByClassName('navList')
      const navWidth = document.getElementsByClassName('nav')[0].clientWidth
      navList[0].scroll({
        top: 0,
        left: (this.currentTab - 2) * navWidth,
        behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
      })
      this.loadGame(item.gametype, item.gamemenutype)
    },
    async loadGame(gametype, gamemenutype) {
      // localStorage.setItem('currentTab', this.currentTab)
      if (gamemenutype !== '998' && gamemenutype !== '999' && gamemenutype !== '888') {
        const res = await getGameLsitbyown({ gametype: gametype, gamemenutype: gamemenutype })
        this.playGameList = res.datalist
        this.allGameList = res.datalist
      } else if (gamemenutype === '888') {
        const res = await getGameplayHotList()
        this.playGameList = res.datalist
        this.allGameList = res.datalist
      } else if (Number(gametype) > 900) {
        this.showTip()
      }
    },
    goPlay(item) {
      // const targetWindow = window.open(undefined, 'game')
      // const routeUrl = this.$router.resolve({ name: 'iframeGame', query: { gametype: item.gametype, playtype: item.playtype }})
      // if (targetWindow) {
      //   window.open(routeUrl.href, 'game')
      // } else {
      //   window.open(routeUrl.href, '_blank')
      // }
      // this.$router.push({ path: '/iframeGame', query: {
      //   gametype: item.gametype,
      //   playtype: item.playtype
      // }})
      // window.open('/#/iframeGame?gametype=' + item.gametype + '&playtype=' + item.playtype)
      window.open(process.env.VUE_APP_BASE_API + '/game/gotoGame?gametype=' + item.gametype + '&playtype=' + item.playtype + '&suid=' + this.$store.getters.token + '&visitorId=' + localStorage.getItem('visitorId'))
    },
    // getUInfoByTokenApi() {
    //   getUInfoByToken({ hbid: this.redbaghbid }).then(res => {
    //     if (res.datalist) {
    //     this.gameTypeList = res.datalist
    //     }
    //   })
    // },
    showTip() {
      this.$toast(this.$t('home.sy42'))
    },
    onSearch() {
      if (this.searchText) {
        this.playGameList = this.allGameList.filter(item => item.playname.includes(this.searchText))
      } else {
        this.loadGame(this.gameTypeList[this.currentTab].gametype, this.gameTypeList[this.currentTab].gamemenutype)
      }
    }
  }
}
</script>
